contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Attempt owner-initiated sendMoney to an arbitrary target with some value and data.
    // We require this contract to have enough balance to forward `amount`.
    function run(address target, uint amount, bytes calldata data) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        require(address(this).balance >= amount);

        // read before values
        uint beforeBalance = address(c).balance;
        uint beforeCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // perform the state-changing call as a top-level call on c
        bool reverted;
        c.sendMoney(target, amount, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // read after values
        uint afterBalance = address(c).balance;
        uint afterCount = c.depositsCount(); if (__ESBMC_reverted()) return;

        // General rule:
        // - If the sendMoney call reverted, c's balance and depositsCount must be unchanged.
        // - If it succeeded, c's balance must have decreased by exactly `amount`. depositsCount is allowed to change only via fallback; sendMoney itself should not change depositsCount.
        assert(
            (reverted && afterBalance == beforeBalance && afterCount == beforeCount)
            || (!reverted && afterBalance + amount == beforeBalance)
        );
    }

    // Allow receiving Ether so this contract can fund calls
    receive() external payable {}
}

